import re
def is_balanced_with_tags(s):
    stack = []
    tokens = re.findall(r'[()\[\]{}]|</?\w+>', s)
    tag_stack = []
    for tok in tokens:
        if tok in '([{':
            stack.append(tok)
        elif tok in ')]}':
            pairs = {')':'(', ']':'[', '}':'{'}
            if not stack or stack.pop() != pairs[tok]:
                return False
        elif tok.startswith('</'):
            if not tag_stack or tag_stack.pop() != tok[2:-1]:
                return False
        elif tok.startswith('<'):
            tag_stack.append(tok[1:-1])
    return not stack and not tag_stack
```
Note: this scans tags and brackets in one pass rather than two, which also works but is slightly harder to read than checking them separately.

